************************************************************************ Patch to Misc.Tools* For ROM 2.0** Copyright 1985-1989* Apple Computer, Inc.* All Rights Reserved** 31 March 88	Steven Glass** The heartbeat interrupt handler needs to be patched out to prevent* it from clearing the quarter second interrupt when it is done * running.** 15 June 88	Harry Yee** Prototype bit taken out of version number. (Version 2.1)** 2? Jul 88	STeven Glass** Patched GetMouseClamps so that code that does not set data bank* can still work.** 26 Jul 88	Steven Glass** Patch DelHeartBeat and ClearHeartbeat to try and turn off vbl * interrupts (if it is safe).** Patch SetVector and GetVector so that they turn interrupts off* before doing their work.** 10 Sep 88	Steven Glass** Added AddToQueue and DeleteFromQueue to call table.** 24 Nov 88	Steven Glass** Added Interrupt State calls to call table.** 13 Jan 89	Steven Glass** Added entries for GetCodeResConverter, ReadMouse2 and ReadMouse in* call table.  ReadMouse is patched to support journaling.  ReadMouse2* just goes to the old ReadMouse address.** 17 Feb 89	S Glass, H Yee** Added patch for GetNewID. We now return errors. BRC #41252.** 3/15/90	Mensch** Add patch for ConvSeconds call. Also, add new address for GetAddr patch* and roll version number.** 9/17/90	Dave Lyons** Changed version to $8302.* Added call table entry for SysBeep2(x).* Fixed GetVector and SetVector to not validate the vector number.** 25-Sep-90	Dave Lyons** Removed "BigMachine proc export" (a word of storage).** 23-Oct-90	Dave Lyons** Added patch entry for UnPackBytes (code is in TS3 misc tools patch).** 10-Dec-90	Dave Lyons** Added VersionString entry (code is in TS3 misc tools patch).** 6-Jan-91	Dave Lyons** Added WaitUntil entry (code is in TS3 misc tools patch).** 4-Mar-91	Dave Lyons** Added StringToText entry (code is in TS3 misc tools patch).** 10-Mar-91	Dave Lyons** Changed NewSysBeep so that if bit 0 of BRAM $5E is clear, meaning* "give visual indication of sounds," we blink the border and allow* the normal sound to happen.** 29-Mar-91	Dave Lyons** Added new calls ShowBootInfo and ScanDevices (code in Patch3:misc).** 20-May-91	Dave Lyons** Patched SysFailMgr to enable text page 1 shadowing and to fix bug* where the high word of the error string pointer is not considered* when checking for NILness.** 17-Sep-91	Dave Lyons** Link some stuff into Tool.Setup instead of TS2/3.  Routines moved* are:  UnPackBytes, ConvSeconds, SysBeep2, VersionString, WaitUntil,* StringToText, ShowBootInfo, ScanDevices.** 5-Feb-92	Dave Lyons** Version $0302 for 6.0 final.************************************************************************** 12-Mar-92	Dave Lyons** Version $8303 for 6.0.1.  (Changed ShowBootInfo in Patch3.)** 23-Jun-92	Dave Lyons** SysFailMgr: Added jsr ComputeDefaultFailMsg to Patch3.  Provides* better default messages for certain errors.** 20-Aug-92	Dave Lyons** Added FPT entries for AlertMessage and DoSysPrefs.** 2-Apr-93 DAL** Version $0303 for 6.0.1.***********************************************************************MTVersionNumber	equ $0303	;2-Apr-93 DALOrigReadMouse	equ $FE9964	include ':::sys.equs.asm'	include 'all.macros'	entry NewSysFail	;added 20-May-91 DALRomVersion	equ 2MTCallTable	PROC	EXPORTHere 	DC.L (TheEnd-Here)/4 ; num calls +1	DC.L MTInit-1	; PowerUp Initialization	DC.L 0	; application startup	DC.L 0	; application shutdown	DC.L MTVer-1	; version number	DC.L 0	; Misc. Tools Reset	DC.L 0	; Reserved	DC.L 0	; Reserved	DC.L 0	; Reserved	DC.L 0	; Write battery ram	DC.L RdBram-1	; Read battery ram	DC.L 0	; Write battery ram	parameter	DC.L RdBParm-1	; Read battery ram parameter	DC.L 0	; read clock w/ hex	format	DC.L 0	; write clock w/ hex format	DC.L 0	; read clock w/ ascii format	DC.L SetVector-1	; set interrupt vector	DC.L GetVector-1	; get interrupt vector	DC.L SetHeart-1	; insert procedure in Heartbeat chain	DC.L DelHeart-1	; delete procedure from heartbeat chai	DC.L ClearHeart-1	; clear heartbeat chain	DC.L NewSysFail-1	; system death manager (patched 20-May-91 DAL)	DC.L GetAddr-1	;  ???	DC.L ReadMouse-1	; Read Mouse	DC.L 0	; initialize mouse	DC.L 0	; set mouse mode	DC.L 0	; home mouse position to min. clamp	DC.L 0	; clear mouse position to 0	DC.L 0	; set both X and Y clamps	DC.L GetMouseClamp-1	; get both X and Y clamps	DC.L 0	; set mouse position	DC.L 0	; service mouse interrupt	DC.L GetNewID-1	; get ID tag	DC.L 0	; delete ID tag	DC.L 0	; get ID tag status	DC.L 0	; enable interrupt source	DC.L 0	; Firmware entry points	DC.L 0	; get tick counter contents	DC.L 0	; Pack bytes	DC.L 0  ;[ts] UnPackBytes-1	; UnPack dem dere bytes	DC.L 0	; This routine munges strings	DC.L 0	; returns IRQ enble	status	DC.L 0	; set absolute device clamps	DC.L 0	; get absolute device clamps	DC.L 0	; system beep	dc.L 0	; NewBasicInit	; added 07 sep 88	DC.L AddToQueue-1		; added 10 sep 88	DC.L DeleteFromQueue-1	; added 10 sep 88	dc.L SetInterruptState-1	; added 24 Nov 88	dc.L GetInterruptState-1	; added 24 Nov 88	dc.L GetIntStateRecSize-1	; added 24 Nov 88	dc.L OrigReadMouse-1	; ReadMouse2 Added 13 Jan 89	dc.L GetCodeResConverter-1	; added 13 Jan 89 {$3403}	dc.L GetRomResource-1	; added 24 Jan 89 ($3503}	dc.L ReleaseRomResource-1	; added 24 Jan 89 {$3603}*** 5.0.3	dc.L 0  ;[ts] ConvSeconds-1	; added 3/14/90 {$3703}*** 6.0	dc.L 0  ;[ts] SysBeep2-1	; added 17-Sep-90 DAL {$3803}	dc.L 0  ;[ts] VersionString-1	; added 10-Dec-90 DAL {$3903}	dc.L 0  ;[ts] WaitUntil-1	; added 6-Jan-91 DAL  {$3A03}	dc.l 0  ;[ts] StringToText-1	; added 4-Mar-91 DAL  {$3B03}	dc.l 0  ;[ts] ShowBootInfo-1	; added 29-Mar-91 DAL {$3C03}	dc.l 0  ;[ts] ScanDevices-1	; added 29-Mar-91 DAL {$3D03}*** 6.0.1	dc.l 0  ;[ts] AlertMessage-1	; added 20-Aug-92 DAL {$3E03}	dc.l 0  ;[ts] DoSysPrefs-1	; added 20-Aug-92 DAL {$3F03}TheEnd	ENDP	EJECT********************************************************************************* Stuff from install.asm* The following few procs have been moved here from install.asm since they must* be used by the rest of the system and the install stuff is now going to be dumped.* at run time********************************************************************************OrigBellVector	proc Export	dc.L 0	ENDP******************************************************************* NewSysBeep** The new sysbeep routine.  This routine calls the old sysbeep* routine if the volume is not set to zero and flashes the* border when it is	set to zero.** Inputs:  None* Outputs: None* all registers preserved* Called in any native mode--mode preserved.** 5/3/90	Mensch* Added code to preserve <X><A> and <Y> since applesoft relies on this* routine to not trash <X> (I figured I would preserve <Y> & <A> while I was at it!******************************************************************	EXPORT NewSysBeepNewSysBeep	PROC	phx	; preserve <X> and <Y> & <A> inside this routine	phy	pha	php	; save m and x	sep #$30	; 8 bit mode	longa off	longi off	lda >IRQ_Volume	; look at the volume	and #$0F	beq VolumeIsZero*** 10-Mar-91 DAL*** If bit 0 of BRAM $5E = 0, user wants visual indication of sounds	lda >$e102c0+$5E	lsr a	bcs VolumeNotZero	phk	per @continue-1	phx	phy	pha	php	bra VolumeIsZero@continue		;fall into VolumeNotZero*** end of 10-Mar-91 DALVolumeNotZero	plp	; nonzero so set carry and get out	pla		ply	; restore <X> and <Y> & <A> here	plx	sec	rtl	VolumeIsZero	phb	; save dbr	pea $E0E0	plb	plb	lda |ClockCtl	and #$0F	pha	; save original border	jsr WaitForVBL	lda #$0F	; force white	tsb |ClockCtl	jsr Wait	jsr WaitForVBL	lda #$0F	; force black	trb |ClockCtl	jsr Wait	jsr WaitForVBL	lda #$0F	; force white	tsb |ClockCtl	jsr Wait	jsr WaitForVBL	lda #$0F	; force black	trb |ClockCtl	jsr Wait	plx	; get restore color	in x	php	; save interrupt status	sei	; ints off	lda #$0F	; force black	trb |ClockCtl	txa	tsb |ClockCtl	; restore orig	plp	; restore ints	plb	; restore dbr	plp	; restore m & x		pla		ply	; restore <X> and <Y> & <A> here	plx	clc	; indicate that I handled bell	rtl;-------------------------------------------------;; WaitForVBL;; Inputs:  None; Outputs: none; Y    preserved NOT <X> (Change comment 5/3/90);; Called in 8-bit mode with data bank set to $E0; Trashes a-reg;; Change History;; 21 Jun 88	Steven Glass;; This routine would wait forever if a VBL task; kept me from reading the counters in time.  So ; we add a timeout counter.;; The counter assumes 18 cycles per loop; 2.8 million cycles per second; 60 vbls a second;; 2800000/60/18 Å 2600;; (Add 200 more for good luck);WaitForVBL	rep #%00010000	longi on	longa off	ldx #2800	; no more than 2800 times through loop@wait	lda |VERTCNT	and #$7F	asl a	cmp #220	bcs @done	dex	bne @wait@done	sep #%00010000	longi off	rts;-------------------------------------------------;; Wait;; Little routine called in mixed native	mode to; call the wait routine.;; Inputs:  none; Outputs: none; All registers trashed.;; Can be called with m or x in any state.  m & x are; preserved.;Wait	php	rep #$30	longa on	longi on	lda #0	pha	pha	pha	pha	pea $00C0	pha	pha	pea $FCA8	; address of wait routine	_FWEntry	pla	pla	pla	pla	plp	rts	longa on	longi on	ENDP*** BigMachine	PROC EXPORT	;removed 25-Sep-90 DAL***	dc.w 0	; assume no!***	ENDP*****************************************************************MTVer	Proc** Returns new version number*** Inputs:*	none** Outputs:*	VersionNumber : word** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #MTVersionNumber	sta 7,s	lda #0	clc	rtl	ENDP*****************************************************************MTInit	PROC** Dummy Init routine prevents real init routine from being* called twice when this patch is installed.*** Inputs:*	none** Outputs:*	none** External Refs:	import FixVector** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #$6B	; init vector to rtl.	sta MIDIInputPoll	jsr FixVector		lda #0	clc	rtl	ENDP****************************************************************** NewSysFail -- ROM 01 patch for SysFailMgr (20-May-91 DAL)** Two fixes to the ROM:*   (1) enable text page 1 shadowing*   (2) check both low and high words of error string pointer*       for NILness*****************************************************************NewSysFail	proc	import ComputeDefaultFailMsg	jsr ComputeDefaultFailMsg	;23-Jun-92 DAL	lda >$e0c035	and #$fffe	sta >$e0c035	clc	lda 7,s	ora 9,s	jml >$fe98ff	EndP	title 'GetAddress'****************************************************************** Return Interrupt Status Address** Input     word	     refnum* Input     LongWord     Don't care** Output    LongWord     Pointer** Modification History**    May 6, 1986	See 5 lines changed	below.*****************************************************************GetAddr	PROCROMGetAddr	equ $FE9909ROMoEndCall2	equ $FEFFB7	ROMoEndCall6	equ $feffcdRTL1	equ 1RTL2	equ RTL1+3RefNum	equ RTL2+3Ptr	equ RefNum+2	lda RefNum,s	; get ref #	cmp #$00FF	; index our special address? ?	beq GetAddrSerial	;	jml ROMGetAddr	; GetAddrSerial		; 	tax	; get param. addr	lda >Ptbl	; abs long,x addressing SEG 6 May 86	sta Ptr,s	lda >Ptbl+2	; abs long,x addressing SEG 6 May 86	sta Ptr+2,s	; missing +2 SEG 6 May 86	jml ROMoEndCall2	; uses oEndCall SEG	6 May 86Ptbl		; 	DC.L $E11dd8	; status of INTFLAG	at IRQPtblEnd		; 	ENDP*****************************************************************RdBram	PROC** Reads the page of battery RAM into the callers buffer.*** Inputs:*	BufferPtr : Long** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 17 Jun 88	Steven Glass** This routine had always called the routine which did an actual* read of the battery RAM.  This is not necessary since the* battery ram buffer is always correct before the read.** Making this change we save the read time (1/10 second with* interrupts off).*****************************************************************OrigDir	equ 1rtl1	equ OrigDir+2rtl2	equ rtl1+3buffer	equ rtl2+3	phd	; turn stack into zp	tsc	tcd		sep #$30	; 8 bit 'm' and 'x'	longi off	longa off		ldx #0	ldy #0movloop	lda >BramBuffer,x	; data from bram buffer	sta [buffer],y	; to user buffer	dex	dey	bne movloop			rep #$30	; 16 bit 'm' and 'x'	longa on	longi on	pld	ldy #4	ldx #0	jmp >ToStrip	ENDP*****************************************************************RdBParm	PROC** Returns the specified byte from the battery RAM on the stack.*** Inputs:*	ID of Parameter to read : word** Outputs:*	Parameter value : word** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 17 Jun 88	Steven Glass** This routine had always called the routine which did an actual* read of the battery RAM.  This is not necessary since the* battery ram buffer is always correct before the read.** Making this change we save the read time (1/10 second with* interrupts off).*****************************************************************	DefineStackRTL1	block 3RTL2	block 3ParamID	wordResultValue	word	lda ParamID,s	; get parm index	and #$00FF	tax	lda >BramBuffer,x	; move from BRAM buffer	and #$00FF	sta ResultValue,s	ldy #2	ldx #0	jmp >ToStrip	ENDP*****************************************************************GetMouseClamp	PROC** See included file.*** Inputs:*	space for four words** Outputs:*	four words of mouse clamps.** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigGetClamp	equ $FE9A75;-----------------------------------------------------------;; This call returns the current mouse clamp values.  The call; is patched because the code in ROM reads a softwitch without; setting the dbr.  We make this work by setting the dbr to 0; and calling the original code.;; The address of OrigGetClamp is defined in the the file; that includes this file so that the same code can be used; for both ROM's.;; Stack Definintion when we get here.;	DefineStackOrigB	bytertl1	block 3rtl2	block 3word4	wordword3	wordword2	wordword1	word	phb	; save the dbr and set dbr to 0	pea $0000	plb	plb	pha	; make the original call	pha	pha	pha	jsl ToOrigGetClamp	tax	; save any error code	pla	; put results of call on the stack.	sta word4+6,s	pla	sta word3+4,s	pla	sta word2+2,s	pla	sta word1,s	plb	; restore dbr	txa	; put any error back in a-reg		; carry still right from call.	rtlToOrigGetClamp	jsl OrigGetClamp	rtl	ENDP************************************************************************ Code to fix the heartbeat handler in ROM.** 31 Mar 88	Steven Glass** The heartbeat handler is installed every time SetHeart is called.* This code patches SetHeart so that it calls the routine in ROM* and then resets the VBL vector.** 26 Jul 88	Steven Glass** Added patches to DelHeartBeat and ClrHeartbeat.  These calls now* call old routines in ROM and then see if it is safe to turn off* the vbl interrupt source.***********************************************************************; from e16.misctoolvblDisable   EQU   $0003 ; Interrupt Ref Number - Parameter to IntSource****************************************************************** Set System Heartbeat Vector*   Input     LongWord     Address** Possible errors are :*     3 = Task error     (task already in queue)*     4 = Header error   (no signature in new task)*     5 = Queue error    (queue got trashed - system fatal)*     6 = Task Not Found*****************************************************************	EXPORT SetHeartSetHeart	PROC	import FixVector	import IRQ_HeartOrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3VPtr	equ RTL2+3	phd	tsc	; make stack into zp	tcd;-----------------------------------------------------------;; First call the old routine in ROM.;	pei VPtr+2	pei VPtr	jsl ToOldCall;-----------------------------------------------------------;; Now, replace the resulting IRQ handler with our own.;	jsr FixVector	pld	ldy #4	lda #0	jml ToStrip	IF ROMVersion = 1 THENToOldCall	jsl $FE9743	ELSEToOldCall	jsl $FE96C9	ENDIF	rtl	ENDP*****************************************************************DelHeart	PROC EXPORT** Deletes the specified heartbeat task from the queue by calling* code in ROM.  Then  Checks to see if no tasks are left, if * all are gone, we check to see if we can turn off vbl interrupts.**** Inputs:*	Pointer to Task to remove.** Outputs:*	none** External Refs:	import IRQ_Heart	import KillIntsIfCan** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3VPtr	equ RTL2+3	phd	tsc	; make stack into zp	tcd;-----------------------------------------------------------;; First call the old routine in ROM.;	pei VPtr+2	pei VPtr	jsl ToOldCall;-----------------------------------------------------------;; Now, turn off vbl interrupts if we can.;	jsr KillIntsIfCan	pld	ldy #4	lda #0	jml ToStrip	IF ROMVersion = 1 THENToOldCall	jsl $FE9823	ELSEToOldCall	jsl $FE97A9	ENDIF	rtl	ENDP*****************************************************************ClearHeart	PROC EXPORT** Deletes all heartbeat tasks from the queue by calling code* in ROM.  Then checks to see if we can turn off vbl interrupts.**** Inputs:*	none** Outputs:*	none** External Refs:	import KillIntsIfCan** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3VPtr	equ RTL2+3	phd;-----------------------------------------------------------;; First call the old routine in ROM.;	jsl ToOldCall;-----------------------------------------------------------;; Now, turn off vbl interrupts if we can.;	jsr KillIntsIfCan	pld	ldy #0	lda #0	jml ToStrip	IF ROMVersion = 1 THENToOldCall	jsl $FE98E0	ELSEToOldCall	jsl $FE9866	ENDIF	rtl	ENDP*****************************************************************KillIntsIfCan	PROC** This routine turns off VBL interrupts if it is safe to do so.* It is safe to turn them off under the following conditions:**   1) No heartbeat tasks are installed.*   2) The heartbeat interrupt vector points to our interrupt*      handler.*   3) the mouse is not running in vbl interrupt mode.*** Inputs:*	none** Outputs:*	none** External Refs:	import IRQ_Heart** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda >HBPtr	ora >HBPtr+2	bne CannotTurnOff		lda >IRQ_VBL+1	cmp #IRQ_Heart	bne CannotTurnOff	lda >IRQ_VBL+2	cmp #>IRQ_Heart	bne CannotTurnOff	pha	pha	pha	_ReadMouse	pla	plx	plx	bcs CanTurnOff	and #%0000000000001000	bne CannotTurnOffCanTurnOff	PushWord #vblDisable	_IntSourceCannotTurnOff	rts	ENDP*****************************************************************FixVector	PROC** Sets the irq vbl vector to point to our patch.*** Inputs:*	none** Outputs:*	none** External Refs:	import IRQ_Heart** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	php	; save IRQ enbl status	sei	; 'cuz no interrupts for now !	lda >NewVector	sta >Irq_VBL	lda >NewVector+2	sta >IRQ_VBL+2	plp	rtsNewVector	jml IRQ_Heart	ENDP****************************************************************** HeartBeat Interrupt Handler** Dispatches to this handler are made in response to VBL* interrupts.   This handler will increment the Tick Counter,* and then each task in the heartbeat interrupt queue will* have its counter decremented.   If a zero value results, the* associated handler will be called.   It is the task's* responsibility to	reset the count each time it is called.** Chain looks like.....** HBptr --> link address --> link address --> $0000*           Counter	         Counter	      counter*           Signature        Signature	      Signature*           (code)	         (code)	      (code)*** Change History** 31 March 88	Steven Glass** Moved the clearing of the interrupt source from the last* thing done to the first thing done.  This is to prevent* this interrupt from clearing other interrupts that are* cleared at the same address.** 14 October 88	Matthew Denman** Added MIDIInputPoll before each task is called, and once at the end.* This will keep us from losing MIDI input data here, unless the task* is longer than 280 microseconds.  If so, they must also poll MIDI* in their task.*****************************************************************	EXPORT IRQ_HeartIRQ_Heart	PROC;-----------------------------------------------------------;; Start by turning off the interrupt source.  Then we can ; go on and run all the installed tasks.;;	sta >ClrVBLint	; turn off interrupt source	rep #$30	; off to 16 bit land	lda >TickCnt	; increment tick counter	inc a	sta >TickCnt	bne TickDone	lda >TickCnt+2	inc a	sta >TickCnt+2TickDone		; 	rep #$30	; off to 16 bit land	lda >HBptr	; is heart beat chain empty	tax	ora >HBptr+2	beq NoChain1	; yes	phb	sep #$20	; 8 bit m	lda >HBptr+2	; point at link	pha	plb	rep #$20	; 16 bit mNextHB		;       	phx	_MidiInputPoll	; Poll Midi before each task.	plx	lda |6,x	; check task signature	cmp #$A55A	beq QueueOK	; looks ok to me	pea $0308	; heartbeat queue error	pea $0000	; Heartbeat queue death message	pea $0000	_SysFailMgr	; off to the system	death handlerQueueOK		; 	lda |4,x	; if cnt = 0, ignore this task	beq NextQueue	dec |4,x	; else decrement task counter	bne NextQueue	; if task cnt not zero, don't execute	phb	; save environment prior to dispatch	phx	phk	; here's where we come back to	pea HBentry-1	phb	; and here's where were going to	clc	txa	adc #7	pha	sep #$30	; dispatch is native, 8 bit m/x	rtl	; and this does the	dispatchHBentry		;       	clc	; native mode, 16 bit m/x	xce	rep #$30	plx	; restore queue pointer	plbNextQueue		;       	lda |0,x	; is this the last link ?	ora |2,x	beq NoChain	; yes	sep #$20	; 8 bit m	lda |2,x	; get next link addr	pha	rep #$20	lda |0,x	tax	plb	bra NextHB	; traverse the chainNoChain	_MidiInputPoll	; Poll one last time just to be safe.       	plbNoChain1		;       	sep #$30	; off to 8 bit land	clc	; flag that interrupt was handled !	rtl	ENDP************************************************************************ Code to fix the setvector and getvector calls in ROM.** 26 Jul 88	Steven Glass** Neither getvector nor setvector turn off interrupts while accessing* the various addresses.  This is not safe since an interrupt could * occur.****************************************************************************************************************************************GetVector	PROC** This patch turns off interrupts, calls the code in ROM and* turns restores the interrupt state.*** Inputs:*	space for result	: long*	id	: word** Outputs:*	vector value	: long** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;*** Old GetVector patch replaced 17-Sep-90 DAL because we want;*** to omit the vector number range-check and be like ROM 3.;	DefineStack;OrigD	word;RTL1	block 3;RTL2	block 3;VectorID	word;ResultSpace	long;;	phd;	tsc;	tcd;;	php;	sei;;	pha;	pha;	pei VectorID;	jsl ToOldCall;	tax;;	pla;	sta ResultSpace;	pla;	sta ResultSpace+2;;	plp;	pld;;	ldy #2;	jml ToStrip;;	IF ROMVersion = 1 THEN;ToOldCall	jsl $FE971E;	ELSE;ToOldCall	jsl $FE96A4;	ENDIF;;	rtlRTL1	equ 1RTL2	equ RTL1+3RefNum	equ RTL2+3Result	equ RefNum+2ROMoEndCall2	equ $FEFFB7		lda RefNum,s	;get reference	and #$00FF	;mask excess	asl a	;and make index	asl a	tax	php	sei	lda >Dispatch1+1,x	sta Result+1,s	lda >Dispatch1+3,x	and #$00FF	sta Result+2+1,s	plp	jmp ROMoEndCall2	ENDP*****************************************************************SetVector	PROC** This patch turns off interrupts, calls the code in ROM and* turns restores the interrupt state.*** Inputs:*	NewAddress	: long*	id	: word** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;*** Old SetVector patch replaced 17-Sep-90 DAL because we want to;*** omit the vector number range-check and be like ROM 3.;	DefineStack;OrigD	word;RTL1	block 3;RTL2	block 3;VectorID	word;NewAddress	long;;	phd;	tsc;	tcd;;	php;	sei;;	pei NewAddress+2;	pei NewAddress;	pei VectorID;	jsl ToOldCall;	tax;;	plp;	pld;;	ldy #6;	jml ToStrip;;	IF ROMVersion = 1 THEN;ToOldCall	jsl $FE96F6;	ELSE;ToOldCall	jsl $FE967C;	ENDIF;;	rtlRTL1	equ 1RTL2	equ RTL1+3NewAdr	equ RTL2+3RefNum	equ NewAdr+4ROMoEndCall6	equ $feffcd	lda RefNum,s	;get reference	and #$00FF	;mask excess	asl a	;and make index	asl a	tax	php	sei	lda NewAdr-1+1,s	;get vector addr 0-7	and #$FF00	;patch 'JML' opcode	in low byte	ora #$005C	sta >Dispatch1,x	lda NewAdr+1+1,s	sta >Dispatch1+2,x	plp	jmp ROMoEndCall6	ENDP	EJECT********************************************************************************ReadMouse	PROC** This call is patched so it can check for journaling.** Inputs:**	word space*	word space*	word space** Outputs:**	word X Position*	word Y Position*	word Status and Mode*** External Refs:	Import AltTRdMouse*********************************************************************************	longa on	longi on;; stack structure;DBreg	equ 1Preg	equ DBreg+1RTL1	equ Preg+1RTL2	equ RTL1+3StatMode	equ RTL2+3YPos	equ StatMode+2XPos	equ YPos+2;	php	;save interrupt status	sei	;disable interrupt	phb	;save data bank;; First, check the journaling flag, if its zero, then simply call ReadMouse direct; and go no further.	lda >JournalFlag	bne ItGetsTrickyOldWay	plb	plp	jml OrigReadMouse;; Next, check to see if the event manager is active, if it is, then we can continue,; if it isn't well, just exit...ItGetsTricky	pha	; room for result	_EMStatus	pla	beq OldWay;; Finally, Look and see whose calling.  If it is the event manager, then we don't; really want to journal.;	lda RTL2+2	and #$00FF	cmp #$00FE	beq OldWay; If we get this far, we know that the event manager is active and that journaling is turned on.	pha	; call the real read mouse to get the current mouse data	pha	pha	_ReadMouse2	pla	; get the current mouse data from the call	ply	plx	sta StatMode,s	; and save them into our record	tya	sta yPos,s	; on the stack for journaling to use.	txa	sta xPos,s;; Now that our result is set properly, we must call the journaling routine so that it will save; these new bytes for us. Or load in whatever it should be for playback; First create the address of our data on the stack so we can pass it	tsc	; get the current stack pointer	clc	adc #StatMode	; add in the proper offset	tax	; and save it in <X> for later	lda >JournalFlag	; first push the flag on the stack	pha	pea $0006	; journal code for ReadMouse (Also the data size...hmmm...)	pea $0000	; now push the address of our data, (its on the stack...)	phx	; push low word of data buffer	jsl JournalPtr	; and call the journaling routine;; Journaling is all finished, and so should we be... so simply exit	plb	;restore data bank	plp	;restore interrupt state during entry	jml oEndCall0	;exit tool with good MouseRead	EndP	title 'ID Tag Manager'*********************************************************************** This tool is used	to insert, delete and inquire status* regarding an ID tag.  The ID tag is used to mark segments* as belonging to a	specific application.** GetNewID*     Input     Word     Space for result*     Input     Word     ID tag (Type and Aux)*     Output    Word     ID tag (Full tag returned)** DeleteID*     Input     Word     ID tag (Type and Main)** StatusID*     Input     Word     ID tag (Type and Main)** ID tag structure is shown below.....*  ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___* |   |   |   |   |	  |   |   |   |   |	  |   |   |   |   |	  |   |* | F | E | D | C |	B | A | 9 | 8 | 7 |	6 | 5 | 4 | 3 | 2 |	1 | 0 |* |___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|*   |___|___|___|	|___|___|___|   |___|___|___|___|___|___|___|*   |	|               |*   Type Field	Aux ID Field    Main ID Field**  Type = 0  Memory	Manager*         1  Application*         2  Controlling Program (Finder, Shell, etc.)*         3  ProDOS*         4  Tool Kits..................Not managed here.*         5  Desk Accessories*         6  Run Time Libraries*         7  System	loader..............Not managed here*         8  Firmware / System Function*         9  Tool Locator...............Not managed here.*         A  Setup File*         B  Undefined*         C  Undefined*         D  Undefined*         E  Undefined*         F  Undefined** Change History** 13 Nov 88	Steven Glass** No longer manage ID 4000, 7000 or 9000. (These are used* throughout the system without anyone reserving them, so we* return error when someone tries to reserve them).** Also removed unnecessary HLock and HUnlock calls.** 17 Feb 89	Glass and Yee** Added to patch. Also removed equate for "bounds". Was not being * used anywhere. Defined BadInputErr also defined in Misc.Tools:misc.tools.asm.**********************************************************************GetNewID	PROC	longa on	longi ontaglist	equ 1size	equ taglist+4SrchTag	equ size+2SrchCnt	equ SrchTag+2OrigDBR	equ SrchCnt+2OrigDir	equ OrigDBR+1rtl1	equ OrigDir+2rtl2	equ rtl1+3UserTag	equ rtl2+3IDTag	equ UserTag+2BadInputErr	equ $0301	DefineStacks_Rtl1	block 3s_Rtl2	block 3s_UserTag	words_result	word	lda s_UserTag,s	and #$F000	cmp #$4000	beq NoCanDo	cmp #$7000	beq NoCanDo	cmp #$9000	bne CanDoNoCanDo	ldx #BadInputErr	jml oErrOut2RealGetNewID 	equ $FE9D52CanDo	jml RealGetNewID	ENDP	END